using CTXD.Server.Data;
using CTXD.Server.Models;
using Npgsql;

namespace CTXD.Server.Services;

public sealed class OfficeService(GameDb db,CanonicalContent content)
{
    public async Task<long> StartPositionBattleAsync(long playerId,int buildingId,int generalId,CancellationToken ct)
    {if(!content.Halls.TryGetValue((buildingId,1),out var hall))throw new GameException("OFFICE_BUILDING_INVALID","Hall building does not exist.");await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var force=await ForceAsync(c,t,playerId,ct);int playerLevel,official;await using(var player=new NpgsqlCommand("SELECT level,official_id FROM players WHERE id=$1 FOR UPDATE",c,t)){player.Parameters.AddWithValue(playerId);await using var r=await player.ExecuteReaderAsync(ct);await r.ReadAsync(ct);playerLevel=r.GetInt32(0);official=r.GetInt32(1);}await using(var ownMembership=new NpgsqlCommand("SELECT 1 FROM player_office_memberships WHERE player_id=$1 AND building_id=$2",c,t)){ownMembership.Parameters.AddWithValue(playerId);ownMembership.Parameters.AddWithValue(buildingId);if(await ownMembership.ExecuteScalarAsync(ct)is not null)throw new GameException("OFFICE_ALREADY_OWNED","Player already belongs to this hall.");}await using(var general=new NpgsqlCommand("SELECT 1 FROM player_generals WHERE player_id=$1 AND general_id=$2 AND general_type=2 AND state<=1 AND forces>0 FOR UPDATE",c,t)){general.Parameters.AddWithValue(playerId);general.Parameters.AddWithValue(generalId);if(await general.ExecuteScalarAsync(ct)is null)throw new GameException("POSITION_GENERAL_INVALID","General cannot enter the position battle.");}int defenderForce=0,defenderLevel=0;await using(var owner=new NpgsqlCommand("SELECT b.owner_player_id,p.level FROM nation_office_buildings b JOIN players p ON p.id=b.owner_player_id WHERE b.force_id=$1 AND b.building_id=$2 FOR UPDATE OF b",c,t)){owner.Parameters.AddWithValue(force);owner.Parameters.AddWithValue(buildingId);await using var r=await owner.ExecuteReaderAsync(ct);if(await r.ReadAsync(ct)){defenderForce=force;defenderLevel=r.GetInt32(1);}}if(defenderLevel==0&&content.Armies.TryGetValue(hall.Chief,out var chief))defenderLevel=chief.GeneralLevel;if(defenderLevel-playerLevel>20)throw new GameException("POSITION_LEVEL_LIMIT","Target exceeds the legacy 20-level attack limit.");await using(var active=new NpgsqlCommand("SELECT 1 FROM world_battle_handoffs WHERE city_id=$1 AND battle_type=4 AND status=0",c,t)){active.Parameters.AddWithValue(buildingId);if(await active.ExecuteScalarAsync(ct)is not null)throw new GameException("POSITION_BATTLE_ACTIVE","Hall already has an active position battle.");}long id;await using(var add=new NpgsqlCommand("INSERT INTO world_battle_handoffs(city_id,attacker_player_id,attacker_general_id,attacker_force_id,defender_force_id,battle_type) VALUES($1,$2,$3,$4,$5,4) RETURNING id",c,t)){add.Parameters.AddWithValue(buildingId);add.Parameters.AddWithValue(playerId);add.Parameters.AddWithValue(generalId);add.Parameters.AddWithValue(force);add.Parameters.AddWithValue(defenderForce);id=Convert.ToInt64(await add.ExecuteScalarAsync(ct));}await using(var state=new NpgsqlCommand("UPDATE player_generals SET state=3,updated_at=now() WHERE player_id=$1 AND general_id=$2",c,t)){state.Parameters.AddWithValue(playerId);state.Parameters.AddWithValue(generalId);await state.ExecuteNonQueryAsync(ct);}await t.CommitAsync(ct);return id;}
    public async Task<IReadOnlyList<OfficeView>> GetAsync(long playerId,CancellationToken ct)
    {await using var c=await db.DataSource.OpenConnectionAsync(ct);var force=await ForceAsync(c,null,playerId,ct);var result=new List<OfficeView>();var rows=new Dictionary<int,(long owner,bool auto)>();await using(var buildings=new NpgsqlCommand("SELECT building_id,owner_player_id,auto_pass FROM nation_office_buildings WHERE force_id=$1",c)){buildings.Parameters.AddWithValue(force);await using var br=await buildings.ExecuteReaderAsync(ct);while(await br.ReadAsync(ct))rows[br.GetInt32(0)]=(br.GetInt64(1),br.GetBoolean(2));}foreach(var hall in content.Halls.Values.Where(x=>x.Degree==1).OrderBy(x=>x.Order).ThenBy(x=>x.Id)){rows.TryGetValue(hall.Id,out var row);var members=new List<OfficeMemberView>();await using var cmd=new NpgsqlCommand("SELECT m.player_id,COALESCE(p.display_name,''),p.level,m.is_leader,m.state FROM player_office_memberships m JOIN players p ON p.id=m.player_id WHERE m.force_id=$1 AND m.building_id=$2 ORDER BY m.is_leader DESC,m.state DESC,p.level DESC",c);cmd.Parameters.AddWithValue(force);cmd.Parameters.AddWithValue(hall.Id);await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))members.Add(new(r.GetInt64(0),r.GetString(1),r.GetInt32(2),r.GetBoolean(3),r.GetInt16(4)));content.Halls.TryGetValue((hall.Id,2),out var normal);result.Add(new(hall.Id,hall.Name,normal?.Name??"",row.owner,row.auto,members));}return result;}

    public async Task ApplyAsync(long playerId,int buildingId,CancellationToken ct)
    {await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var force=await ForceAsync(c,t,playerId,ct);if(!content.Halls.ContainsKey((buildingId,1))||buildingId is 18 or 19)throw new GameException("OFFICE_BUILDING_INVALID","This office cannot receive applications.");long owner;bool auto;int count;await using(var cmd=new NpgsqlCommand("SELECT owner_player_id,auto_pass,member_count FROM nation_office_buildings WHERE force_id=$1 AND building_id=$2 FOR UPDATE",c,t)){cmd.Parameters.AddWithValue(force);cmd.Parameters.AddWithValue(buildingId);await using var r=await cmd.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("OFFICE_NO_OWNER","Office building has no owner.");owner=r.GetInt64(0);auto=r.GetBoolean(1);count=r.GetInt32(2);}await using(var exists=new NpgsqlCommand("SELECT 1 FROM player_office_memberships WHERE player_id=$1",c,t)){exists.Parameters.AddWithValue(playerId);if(await exists.ExecuteScalarAsync(ct)is not null)throw new GameException("OFFICE_ALREADY_MEMBER","Player already holds or applies for an office.");}if(auto&&count>=3)throw new GameException("OFFICE_MEMBER_FULL","Office already has three members.");var accepted=auto;await using(var add=new NpgsqlCommand("INSERT INTO player_office_memberships(player_id,force_id,building_id,is_leader,state) VALUES($1,$2,$3,false,$4)",c,t)){add.Parameters.AddWithValue(playerId);add.Parameters.AddWithValue(force);add.Parameters.AddWithValue(buildingId);add.Parameters.AddWithValue(accepted?1:0);await add.ExecuteNonQueryAsync(ct);}if(accepted){await AcceptCoreAsync(c,t,force,buildingId,playerId,ct);}await t.CommitAsync(ct);}

    public Task AcceptAsync(long leader,long applicant,CancellationToken ct)=>DecideAsync(leader,applicant,true,ct);
    public Task RefuseAsync(long leader,long applicant,CancellationToken ct)=>DecideAsync(leader,applicant,false,ct);
    async Task DecideAsync(long leader,long applicant,bool accept,CancellationToken ct)
    {await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var membership=await LeaderAsync(c,t,leader,ct);await using(var check=new NpgsqlCommand("SELECT 1 FROM player_office_memberships WHERE player_id=$1 AND force_id=$2 AND building_id=$3 AND state=0 FOR UPDATE",c,t)){check.Parameters.AddWithValue(applicant);check.Parameters.AddWithValue(membership.force);check.Parameters.AddWithValue(membership.building);if(await check.ExecuteScalarAsync(ct)is null)throw new GameException("OFFICE_APPLICATION_MISSING","Application does not exist.");}if(accept){int count;await using(var lockBuilding=new NpgsqlCommand("SELECT member_count FROM nation_office_buildings WHERE force_id=$1 AND building_id=$2 FOR UPDATE",c,t)){lockBuilding.Parameters.AddWithValue(membership.force);lockBuilding.Parameters.AddWithValue(membership.building);count=Convert.ToInt32(await lockBuilding.ExecuteScalarAsync(ct));}if(count>=3)throw new GameException("OFFICE_MEMBER_FULL","Office already has three members.");await AcceptCoreAsync(c,t,membership.force,membership.building,applicant,ct);}else{await using var remove=new NpgsqlCommand("DELETE FROM player_office_memberships WHERE player_id=$1",c,t);remove.Parameters.AddWithValue(applicant);await remove.ExecuteNonQueryAsync(ct);}await t.CommitAsync(ct);}

    public async Task KickAsync(long leader,long member,CancellationToken ct)
    {await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var own=await LeaderAsync(c,t,leader,ct);await using(var remove=new NpgsqlCommand("DELETE FROM player_office_memberships WHERE player_id=$1 AND force_id=$2 AND building_id=$3 AND is_leader=false AND state=1",c,t)){remove.Parameters.AddWithValue(member);remove.Parameters.AddWithValue(own.force);remove.Parameters.AddWithValue(own.building);if(await remove.ExecuteNonQueryAsync(ct)!=1)throw new GameException("OFFICE_MEMBER_MISSING","Accepted member does not exist.");}await ResetOfficialAsync(c,t,member,ct);await using(var count=new NpgsqlCommand("UPDATE nation_office_buildings SET member_count=member_count-1 WHERE force_id=$1 AND building_id=$2",c,t)){count.Parameters.AddWithValue(own.force);count.Parameters.AddWithValue(own.building);await count.ExecuteNonQueryAsync(ct);}await t.CommitAsync(ct);}

    public async Task SetAutoPassAsync(long leader,bool enabled,CancellationToken ct){await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var own=await LeaderAsync(c,t,leader,ct);if(own.building is 18 or 19)throw new GameException("OFFICE_AUTOPASS_INVALID","This office cannot use auto-pass.");await using var cmd=new NpgsqlCommand("UPDATE nation_office_buildings SET auto_pass=$3 WHERE force_id=$1 AND building_id=$2",c,t);cmd.Parameters.AddWithValue(own.force);cmd.Parameters.AddWithValue(own.building);cmd.Parameters.AddWithValue(enabled);await cmd.ExecuteNonQueryAsync(ct);await t.CommitAsync(ct);}

    public async Task QuitAsync(long playerId,CancellationToken ct)
    {await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);int force,building,state;bool leader;await using(var cmd=new NpgsqlCommand("SELECT force_id,building_id,is_leader,state FROM player_office_memberships WHERE player_id=$1 FOR UPDATE",c,t)){cmd.Parameters.AddWithValue(playerId);await using var r=await cmd.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("OFFICE_NOT_MEMBER","Player has no office membership.");force=r.GetInt16(0);building=r.GetInt32(1);leader=r.GetBoolean(2);state=r.GetInt16(3);}await using(var remove=new NpgsqlCommand("DELETE FROM player_office_memberships WHERE player_id=$1",c,t)){remove.Parameters.AddWithValue(playerId);await remove.ExecuteNonQueryAsync(ct);}await ResetOfficialAsync(c,t,playerId,ct);if(!leader){if(state==1)await ChangeCountAsync(c,t,force,building,-1,ct);}else{var candidates=new List<(long id,int level)>();await using(var list=new NpgsqlCommand("SELECT m.player_id,p.level FROM player_office_memberships m JOIN players p ON p.id=m.player_id WHERE m.force_id=$1 AND m.building_id=$2 AND m.state=1 ORDER BY p.level DESC,m.player_id",c,t)){list.Parameters.AddWithValue(force);list.Parameters.AddWithValue(building);await using var r=await list.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))candidates.Add((r.GetInt64(0),r.GetInt32(1)));}if(candidates.Count==0){await using var clear=new NpgsqlCommand("DELETE FROM player_office_memberships WHERE force_id=$1 AND building_id=$2 AND state=0;DELETE FROM nation_office_buildings WHERE force_id=$1 AND building_id=$2",c,t);clear.Parameters.AddWithValue(force);clear.Parameters.AddWithValue(building);await clear.ExecuteNonQueryAsync(ct);}else{var next=candidates[0].id;await using var promote=new NpgsqlCommand("UPDATE player_office_memberships SET is_leader=true WHERE player_id=$1;UPDATE nation_office_buildings SET owner_player_id=$1,member_count=member_count-1 WHERE force_id=$2 AND building_id=$3",c,t);promote.Parameters.AddWithValue(next);promote.Parameters.AddWithValue(force);promote.Parameters.AddWithValue(building);await promote.ExecuteNonQueryAsync(ct);await SetOfficialAsync(c,t,next,building,1,ct);}}await t.CommitAsync(ct);}

    public async Task ResolveBattleAsync(int force,int building,IReadOnlyList<long> orderedPlayers,CancellationToken ct)
    {if(orderedPlayers.Count==0||!content.Halls.ContainsKey((building,1)))return;await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var displaced=new List<long>();await using(var old=new NpgsqlCommand("SELECT player_id FROM player_office_memberships WHERE force_id=$1 AND building_id=$2",c,t)){old.Parameters.AddWithValue(force);old.Parameters.AddWithValue(building);await using var r=await old.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))displaced.Add(r.GetInt64(0));}foreach(var id in displaced)await ResetOfficialAsync(c,t,id,ct);await using(var clear=new NpgsqlCommand("DELETE FROM player_office_memberships WHERE force_id=$1 AND building_id=$2;DELETE FROM nation_office_buildings WHERE force_id=$1 AND building_id=$2",c,t)){clear.Parameters.AddWithValue(force);clear.Parameters.AddWithValue(building);await clear.ExecuteNonQueryAsync(ct);}var winners=orderedPlayers.Take(3).ToArray();await using(var owner=new NpgsqlCommand("INSERT INTO nation_office_buildings(force_id,building_id,owner_player_id,member_count) VALUES($1,$2,$3,$4)",c,t)){owner.Parameters.AddWithValue(force);owner.Parameters.AddWithValue(building);owner.Parameters.AddWithValue(winners[0]);owner.Parameters.AddWithValue(winners.Length);await owner.ExecuteNonQueryAsync(ct);}for(var i=0;i<winners.Length;i++){await using var add=new NpgsqlCommand("INSERT INTO player_office_memberships(player_id,force_id,building_id,is_leader,state,is_new) VALUES($1,$2,$3,$4,1,true) ON CONFLICT(player_id) DO UPDATE SET force_id=$2,building_id=$3,is_leader=$4,state=1,is_new=true",c,t);add.Parameters.AddWithValue(winners[i]);add.Parameters.AddWithValue(force);add.Parameters.AddWithValue(building);add.Parameters.AddWithValue(i==0);await add.ExecuteNonQueryAsync(ct);await SetOfficialAsync(c,t,winners[i],building,i==0?1:2,ct);}await t.CommitAsync(ct);}

    async Task AcceptCoreAsync(NpgsqlConnection c,NpgsqlTransaction t,int force,int building,long player,CancellationToken ct){await using(var cmd=new NpgsqlCommand("UPDATE player_office_memberships SET state=1 WHERE player_id=$1;UPDATE nation_office_buildings SET member_count=member_count+1 WHERE force_id=$2 AND building_id=$3",c,t)){cmd.Parameters.AddWithValue(player);cmd.Parameters.AddWithValue(force);cmd.Parameters.AddWithValue(building);await cmd.ExecuteNonQueryAsync(ct);}await SetOfficialAsync(c,t,player,building,2,ct);}
    async Task SetOfficialAsync(NpgsqlConnection c,NpgsqlTransaction t,long player,int building,int degree,CancellationToken ct){if(!content.Halls.TryGetValue((building,degree),out var hall))throw new GameException("HALL_STATIC_MISSING","Hall rank is missing.",500);await using var cmd=new NpgsqlCommand("UPDATE players SET official_id=$2,updated_at=now() WHERE id=$1",c,t);cmd.Parameters.AddWithValue(player);cmd.Parameters.AddWithValue(hall.OfficialId);await cmd.ExecuteNonQueryAsync(ct);}
    static async Task ResetOfficialAsync(NpgsqlConnection c,NpgsqlTransaction t,long player,CancellationToken ct){await using var cmd=new NpgsqlCommand("UPDATE players SET official_id=13,updated_at=now() WHERE id=$1",c,t);cmd.Parameters.AddWithValue(player);await cmd.ExecuteNonQueryAsync(ct);}
    static async Task ChangeCountAsync(NpgsqlConnection c,NpgsqlTransaction t,int force,int building,int delta,CancellationToken ct){await using var cmd=new NpgsqlCommand("UPDATE nation_office_buildings SET member_count=member_count+$3 WHERE force_id=$1 AND building_id=$2",c,t);cmd.Parameters.AddWithValue(force);cmd.Parameters.AddWithValue(building);cmd.Parameters.AddWithValue(delta);await cmd.ExecuteNonQueryAsync(ct);}
    static async Task<int> ForceAsync(NpgsqlConnection c,NpgsqlTransaction? t,long player,CancellationToken ct){await using var cmd=new NpgsqlCommand("SELECT force_id FROM players WHERE id=$1",c,t);cmd.Parameters.AddWithValue(player);var force=Convert.ToInt32(await cmd.ExecuteScalarAsync(ct));if(force is <1 or >3)throw new GameException("NATION_NOT_CHOSEN","Choose a nation first.");return force;}
    static async Task<(int force,int building)> LeaderAsync(NpgsqlConnection c,NpgsqlTransaction t,long player,CancellationToken ct){await using var cmd=new NpgsqlCommand("SELECT force_id,building_id FROM player_office_memberships WHERE player_id=$1 AND is_leader=true AND state=1 FOR UPDATE",c,t);cmd.Parameters.AddWithValue(player);await using var r=await cmd.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("OFFICE_NOT_LEADER","Only the office leader may do this.",403);return(r.GetInt16(0),r.GetInt32(1));}
}
